import { Q, cat, type Raw } from "@/content/helpers";

/* Lote de aprofundamento de SQL. Cada comando traz uma consulta que o usuário pode rodar na hora (SQLite no navegador).
   Onde o dialeto muda (MySQL, PostgreSQL, SQL Server), o texto explica a diferença. */

type Demo = { db: "loja" | "escola" | "rh"; query: string };
export const SQL_NEW_DEMOS: Record<string, Demo> = {};

/** Entrada com consulta executável: o exemplo exibido é a própria consulta. */
const D = (db: Demo["db"], query: string, o: Raw) => {
  SQL_NEW_DEMOS[o.s] = { db, query };
  return Q({ ...o, ex: o.ex ?? query });
};

export const sqlC = [
  cat("dml-detalhado", "Inserir, Alterar e Apagar em Detalhe", "Além do básico: várias linhas de uma vez, upsert, RETURNING e a diferença entre DELETE, TRUNCATE e DROP.", [
    D("loja", `INSERT INTO produtos (nome, categoria, preco, estoque) VALUES\n  ('Pen drive 64 GB', 'Acessórios', 45, 100),\n  ('Mousepad grande', 'Acessórios', 25, 80);\n\n-- Um INSERT com várias linhas é MUITO mais rápido que vários INSERTs separados\nSELECT id, nome, preco FROM produtos ORDER BY id DESC LIMIT 3;`,
      { s: "insert-multiplos", t: "INSERT de várias linhas", d: "Grava várias linhas em um único comando.", x: "INSERT INTO tabela (c1, c2) VALUES (a, b), (c, d), (e, f);",
        n: "Separe cada linha com vírgula dentro do mesmo VALUES. Além de mais curto, é bem mais rápido: o banco processa um comando só, em vez de vários.\nSe uma das linhas violar uma regra (UNIQUE, NOT NULL...), o comando inteiro falha e nada é gravado. Para cargas grandes, divida em lotes de algumas centenas ou milhares de linhas.",
        u: "Importar ou semear dados|Gravar itens de um carrinho de uma vez", a: "Montar o texto do INSERT concatenando valores digitados pelo usuário (veja SQL injection)", r: "sql/dml-detalhado/insert-select|sql/avancado/insert", k: "inserir várias linhas|vários inserts|carga de dados|inserir em lote|insert múltiplo|popular tabela" }),
    D("loja", `CREATE TABLE clientes_rn (id INTEGER, nome TEXT, cidade TEXT);\n\n-- Copia o resultado de um SELECT para dentro de outra tabela\nINSERT INTO clientes_rn (id, nome, cidade)\nSELECT id, nome, cidade FROM clientes WHERE estado = 'RN';\n\nSELECT * FROM clientes_rn;`,
      { s: "insert-select", t: "INSERT ... SELECT", d: "Grava em uma tabela o resultado de uma consulta.", x: "INSERT INTO destino (colunas) SELECT colunas FROM origem WHERE ...;",
        n: "Em vez de VALUES, você passa um SELECT. É o jeito de copiar dados entre tabelas, gerar tabelas de resumo, arquivar linhas antigas e migrar dados após mudar o modelo.\nAs colunas do SELECT precisam combinar, em ordem e tipo, com as colunas listadas no INSERT. CREATE TABLE ... AS SELECT (CTAS) cria a tabela destino já com o resultado.",
        u: "Copiar ou arquivar dados|Criar tabelas de resumo|Migrar dados entre tabelas", r: "sql/dml-detalhado/insert-multiplos", k: "copiar dados entre tabelas|inserir resultado de consulta|insert select|arquivar linhas|duplicar tabela" }),
    D("loja", `CREATE TABLE contador_vendas (produto_id INTEGER PRIMARY KEY, total INTEGER);\nINSERT INTO contador_vendas VALUES (1, 10);\n\n-- Se o produto já existe, SOMA; se não existe, INSERE\nINSERT INTO contador_vendas (produto_id, total) VALUES (1, 5), (2, 7)\nON CONFLICT (produto_id) DO UPDATE SET total = total + excluded.total;\n\nSELECT * FROM contador_vendas;`,
      { s: "upsert", t: "UPSERT (inserir ou atualizar)", d: "Insere a linha; se já existir (chave repetida), atualiza em vez de dar erro.", x: "INSERT ... ON CONFLICT (chave) DO UPDATE SET ...;",
        n: "Resolve o padrão 'se existe, atualize; senão, crie' em um único comando atômico, sem precisar consultar antes (o que causa condição de corrida entre dois usuários).\nA sintaxe muda por banco: SQLite e PostgreSQL usam ON CONFLICT ... DO UPDATE (e 'excluded' para o valor que seria inserido); MySQL usa ON DUPLICATE KEY UPDATE; SQL Server usa MERGE.\nExige uma restrição UNIQUE ou PRIMARY KEY na coluna do conflito.",
        ex: `-- SQLite / PostgreSQL\nINSERT INTO contador (id, total) VALUES (1, 5)\nON CONFLICT (id) DO UPDATE SET total = contador.total + excluded.total;\n\n-- MySQL\nINSERT INTO contador (id, total) VALUES (1, 5)\nON DUPLICATE KEY UPDATE total = total + VALUES(total);\n\n-- SQL Server\nMERGE contador AS t USING (SELECT 1 AS id, 5 AS total) AS s ON t.id = s.id\nWHEN MATCHED THEN UPDATE SET t.total = t.total + s.total\nWHEN NOT MATCHED THEN INSERT (id, total) VALUES (s.id, s.total);`,
        u: "Contadores e métricas|Sincronizar dados vindos de fora|Salvar configurações por usuário", r: "sql/dml-detalhado/returning|sql/transacoes/unique-not-null", k: "inserir ou atualizar|se existe atualiza senão insere|on conflict|on duplicate key|merge|evitar duplicidade ao inserir|upsert" }),
    D("loja", `-- Zera o estoque de quem nunca foi vendido\nUPDATE produtos\nSET estoque = 0\nWHERE id NOT IN (SELECT DISTINCT produto_id FROM itens_pedido);\n\nSELECT nome, estoque FROM produtos WHERE estoque = 0;`,
      { s: "update-subquery", t: "UPDATE com subconsulta", d: "Altera linhas com base no resultado de outra consulta.", x: "UPDATE t SET coluna = (SELECT ...) WHERE id IN (SELECT ...);",
        n: "A subconsulta pode estar no WHERE (para escolher quais linhas mudam) ou no SET (para calcular o novo valor, inclusive vinda de outra tabela).\nBoa prática: rode primeiro o SELECT equivalente para ver QUAIS linhas serão afetadas, e só depois troque por UPDATE. Em produção, faça dentro de uma transação para poder dar ROLLBACK.\nPostgreSQL e SQL Server também permitem UPDATE ... FROM (junção direta); no MySQL é UPDATE a JOIN b.",
        a: "Rodar sem WHERE (altera a tabela inteira)", r: "sql/avancado/update|sql/transacoes/begin-commit-rollback", k: "atualizar com base em outra tabela|update com select|update com join|atualizar linhas que não existem em outra tabela" }),
    D("loja", `-- RETURNING devolve as linhas que acabaram de ser alteradas\nUPDATE produtos\nSET preco = ROUND(preco * 1.05, 2)\nWHERE categoria = 'Móveis'\nRETURNING id, nome, preco;`,
      { s: "returning", t: "RETURNING", d: "Devolve as linhas afetadas por INSERT, UPDATE ou DELETE, sem um SELECT extra.", x: "INSERT ... RETURNING id;\nUPDATE ... RETURNING *;\nDELETE ... RETURNING coluna;",
        n: "Muito útil para pegar o id gerado automaticamente em um INSERT, ou para saber exatamente o que foi apagado/alterado, tudo em uma só viagem ao banco.\nDisponível em PostgreSQL, SQLite (3.35+) e MariaDB. No SQL Server a palavra é OUTPUT; o MySQL não tem equivalente direto (use LAST_INSERT_ID()).",
        r: "sql/dml-detalhado/upsert", k: "pegar id gerado|devolver linhas alteradas|output|last insert id|retornar o que foi apagado" }),
    D("loja", `CREATE TABLE logs (id INTEGER PRIMARY KEY, msg TEXT);\nINSERT INTO logs (msg) VALUES ('a'), ('b'), ('c');\n\nDELETE FROM logs WHERE msg = 'b';      -- remove só o que combina\nSELECT COUNT(*) AS restantes FROM logs;\n\nDELETE FROM logs;                      -- esvazia a tabela (a estrutura continua)\nSELECT COUNT(*) AS depois FROM logs;\n\nDROP TABLE logs;                       -- apaga a tabela inteira, estrutura incluída\nSELECT name FROM sqlite_master WHERE name = 'logs';`,
      { s: "delete-vs-truncate", t: "DELETE vs TRUNCATE vs DROP", d: "Três jeitos de remover dados, com alcance e riscos muito diferentes.", x: "DELETE FROM t WHERE ...;\nTRUNCATE TABLE t;\nDROP TABLE t;",
        n: "DELETE remove linhas (com ou sem WHERE), registra cada uma, dispara gatilhos e pode ser desfeito em transação. TRUNCATE esvazia a tabela inteira de uma vez: bem mais rápido, geralmente zera contadores automáticos e não aceita WHERE. DROP remove a tabela inteira: dados E estrutura.\nO SQLite não tem TRUNCATE (use DELETE sem WHERE). No MySQL o TRUNCATE não pode ser revertido; no PostgreSQL e SQL Server, dentro de transação, pode.\nRegra de ouro: antes de qualquer DELETE, rode o mesmo comando como SELECT para conferir o que será afetado.",
        a: "DELETE sem WHERE em produção sem backup", r: "sql/avancado/delete|sql/ddl/drop-table", k: "apagar todas as linhas|limpar tabela|truncate|diferença delete e drop|esvaziar tabela|zerar tabela" }),
  ]),

  cat("textos-numeros", "Textos, Números e NULL", "Funções para manipular texto e números, e como evitar os erros clássicos de divisão por zero e NULL.", [
    D("loja", `SELECT nome,\n  UPPER(nome)                         AS maiusculo,\n  LENGTH(nome)                        AS tamanho,\n  SUBSTR(nome, 1, 3)                  AS tres_primeiras,\n  REPLACE(email, '@', ' [arroba] ')   AS email_ofuscado,\n  TRIM('   com espaços   ')           AS aparado,\n  nome || ' - ' || cidade             AS ficha\nFROM clientes\nWHERE email IS NOT NULL\nLIMIT 5;`,
      { s: "funcoes-texto", t: "Funções de texto (UPPER, SUBSTR, REPLACE, ||)", d: "Transformar, cortar, juntar e medir textos.", x: "UPPER(t), LOWER(t), LENGTH(t), SUBSTR(t, início, tamanho), REPLACE(t, de, para), TRIM(t), a || b",
        n: "As mais usadas: UPPER/LOWER (caixa), TRIM (tira espaços das pontas), SUBSTR (corta um pedaço; o 1º caractere é a posição 1), REPLACE (troca trechos), LENGTH (tamanho) e a concatenação.\nConcatenar muda por banco: || no SQLite e PostgreSQL; CONCAT(a, b) no MySQL (onde || é 'OU' lógico por padrão!) e no SQL Server (que também aceita +). Lembre: concatenar com NULL dá NULL na maioria dos bancos; use COALESCE.",
        ex: `-- SQLite / PostgreSQL\nSELECT nome || ' - ' || cidade FROM clientes;\n\n-- MySQL / SQL Server 2012+ / PostgreSQL\nSELECT CONCAT(nome, ' - ', cidade) FROM clientes;\n\n-- SQL Server\nSELECT nome + ' - ' + cidade FROM clientes;`,
        r: "sql/funcoes/coalesce|sql/consultas/like", k: "juntar textos|concatenar|cortar texto|maiúsculas|remover espaços|trocar texto|tamanho do texto|substring|concat" }),
    D("loja", `SELECT nome, preco,\n  ROUND(preco / 3, 2)               AS terco,\n  CAST(preco AS INTEGER) / 7        AS divisao_inteira,\n  CAST(preco AS INTEGER) % 7        AS resto,\n  ABS(preco - 200)                  AS distancia_de_200,\n  MAX(preco, 100)                   AS no_minimo_100   -- no SQLite, MAX(a,b) compara dois valores\nFROM produtos\nLIMIT 6;`,
      { s: "funcoes-numericas", t: "Funções numéricas (ROUND, ABS, %, divisão)", d: "Arredondar, calcular resto, valor absoluto e cuidar da divisão inteira.", x: "ROUND(n, casas), ABS(n), n % d, CEIL(n), FLOOR(n)",
        n: "ROUND arredonda (ROUND(2.567, 2) = 2.57). CEIL/CEILING arredonda para cima e FLOOR para baixo (no SQLite recente também existem). % dá o resto da divisão (útil para pares/ímpares e ciclos).\nCuidado com a divisão inteira: em vários bancos 10 / 4 = 2 (dois inteiros). Force decimal com 10 / 4.0 ou CAST. No PostgreSQL e SQL Server isso é regra; no MySQL o operador / já devolve decimal e DIV é a divisão inteira.",
        r: "sql/funcoes/cast|sql/textos-numeros/nullif", k: "arredondar|resto da divisão|módulo|valor absoluto|divisão inteira|casas decimais|round|arredondar para cima" }),
    D("loja", `-- Preço por unidade em estoque. Estoque 0 causaria divisão por zero.\nSELECT nome, estoque,\n  ROUND(preco / NULLIF(estoque, 0), 2) AS preco_por_unidade\nFROM produtos\nORDER BY estoque;\n\n-- NULLIF(a, b) devolve NULL quando a = b. E NULL propaga: o resultado vira NULL em vez de erro.`,
      { s: "nullif", t: "NULLIF (evitar divisão por zero)", d: "Devolve NULL se dois valores forem iguais; é o antídoto da divisão por zero.", x: "NULLIF(a, b)  -- NULL quando a = b",
        n: "Dividir por zero dá ERRO no PostgreSQL, SQL Server e outros (no SQLite e MySQL devolve NULL). Com NULLIF(divisor, 0) o divisor 0 vira NULL e o resultado inteiro vira NULL, sem erro, em qualquer banco.\nTambém serve para transformar texto vazio em NULL: NULLIF(campo, ''). Combine com COALESCE para dar um valor padrão ao resultado.",
        ex: `-- Portável: nunca dá erro de divisão por zero\nSELECT total / NULLIF(quantidade, 0) FROM vendas;\n\n-- Com valor padrão quando não dá para calcular\nSELECT COALESCE(total / NULLIF(quantidade, 0), 0) FROM vendas;\n\n-- Transformar texto vazio em NULL\nSELECT NULLIF(telefone, '') FROM clientes;`,
        r: "sql/funcoes/coalesce|sql/textos-numeros/funcoes-numericas", k: "divisão por zero|evitar erro de divisão|texto vazio vira null|nullif|erro divide by zero" }),
  ]),

  cat("subqueries-conjuntos", "Subconsultas, Conjuntos e Paginação", "IN vs EXISTS, subconsultas correlacionadas, INTERSECT/EXCEPT e como paginar resultados.", [
    D("loja", `-- 1) IN\nSELECT nome FROM clientes\nWHERE id IN (SELECT cliente_id FROM pedidos WHERE status = 'cancelado');\n\n-- 2) EXISTS: mesmo resultado, escrito de outro jeito\nSELECT nome FROM clientes c\nWHERE EXISTS (SELECT 1 FROM pedidos p WHERE p.cliente_id = c.id AND p.status = 'cancelado');\n\n-- 3) A ARMADILHA do NOT IN: se a lista tiver um NULL, o resultado é VAZIO\nSELECT COUNT(*) AS clientes_encontrados\nFROM clientes\nWHERE id NOT IN (SELECT 1 UNION SELECT NULL);`,
      { s: "in-vs-exists", t: "IN vs EXISTS (e a armadilha do NOT IN)", d: "Dois jeitos de testar pertencimento; um deles tem uma pegadinha com NULL.", x: "WHERE col IN (SELECT ...)\nWHERE EXISTS (SELECT 1 FROM ... WHERE ...)",
        n: "IN compara com uma LISTA de valores. EXISTS só pergunta 'a subconsulta devolve alguma linha?' e para na primeira. Para quem lê, IN costuma ser mais claro; EXISTS tende a ser mais eficiente em tabelas grandes e permite condições com várias colunas.\nA pegadinha: NOT IN com um NULL na lista não devolve NADA (porque x <> NULL é desconhecido). Prefira NOT EXISTS, que se comporta como esperado.\nBancos modernos otimizam os dois de forma parecida; escolha pela clareza e pela segurança contra NULL.",
        u: "NOT EXISTS para 'quem não tem...'|EXISTS quando a condição envolve várias colunas", a: "NOT IN em subconsulta que pode ter NULL", r: "sql/joins-avancados/exists|sql/funcoes/subquery", k: "in ou exists|not in não funciona|not in com null|diferença entre in e exists|quem não tem pedido|not exists" }),
    D("loja", `-- O pedido de maior valor de CADA cliente\n-- A subconsulta usa p.cliente_id da consulta de fora: por isso é "correlacionada"\nSELECT p.cliente_id, p.id AS pedido, p.total\nFROM pedidos p\nWHERE p.total = (\n  SELECT MAX(x.total) FROM pedidos x WHERE x.cliente_id = p.cliente_id\n)\nORDER BY p.cliente_id;`,
      { s: "subquery-correlacionada", t: "Subconsulta correlacionada", d: "Subconsulta que depende da linha da consulta externa e roda uma vez por linha.", x: "SELECT ... FROM a WHERE x = (SELECT ... FROM b WHERE b.id = a.id)",
        n: "Diferente da subconsulta comum (roda uma vez), a correlacionada referencia a tabela de fora e é reavaliada para cada linha. É poderosa para 'o maior/mais recente de cada grupo', mas pode ser lenta em tabelas grandes.\nAlternativas mais rápidas e legíveis: funções de janela (ROW_NUMBER, RANK com PARTITION BY) ou uma CTE com GROUP BY e um JOIN.",
        r: "sql/window-functions/row-number-rank|sql/views-cte/with-cte", k: "o maior de cada grupo|mais recente de cada cliente|subconsulta dependente|subquery correlacionada|top por categoria" }),
    D("loja", `-- Clientes que compraram produtos de Informática E de Periféricos\nSELECT DISTINCT p.cliente_id\nFROM pedidos p JOIN itens_pedido i ON i.pedido_id = p.id JOIN produtos pr ON pr.id = i.produto_id\nWHERE pr.categoria = 'Informática'\nINTERSECT\nSELECT DISTINCT p.cliente_id\nFROM pedidos p JOIN itens_pedido i ON i.pedido_id = p.id JOIN produtos pr ON pr.id = i.produto_id\nWHERE pr.categoria = 'Periféricos';\n\n-- Troque INTERSECT por EXCEPT: compraram Informática, mas NUNCA Periféricos`,
      { s: "intersect-except", t: "INTERSECT e EXCEPT", d: "Operações de conjunto: o que está nos dois resultados, ou só no primeiro.", x: "SELECT ... INTERSECT SELECT ...;\nSELECT ... EXCEPT SELECT ...;",
        n: "UNION junta, INTERSECT devolve só o que aparece nos DOIS resultados e EXCEPT o que está no primeiro e não no segundo (no Oracle chama-se MINUS). Todos removem linhas repetidas por padrão; as versões ... ALL mantêm repetições onde o banco suporta.\nAs duas consultas precisam ter o mesmo número de colunas, com tipos compatíveis. O MySQL só passou a suportar INTERSECT e EXCEPT na versão 8.0.31.",
        r: "sql/joins-avancados/union|sql/subqueries-conjuntos/in-vs-exists", k: "quem está nos dois|interseção|diferença entre conjuntos|comprou x mas não y|except|minus|intersect" }),
    D("loja", `-- Página 2, com 5 itens por página:  OFFSET = (página - 1) * 5\nSELECT id, nome, preco FROM produtos ORDER BY id LIMIT 5 OFFSET 5;\n\n-- Paginação por "cursor" (keyset): continua a partir do último id que você viu\nSELECT id, nome, preco FROM produtos WHERE id > 5 ORDER BY id LIMIT 5;`,
      { s: "paginacao", t: "Paginação (LIMIT/OFFSET vs keyset)", d: "Como dividir resultados em páginas, e por que OFFSET fica lento em tabelas grandes.", x: "LIMIT 10 OFFSET 20\nWHERE id > :ultimo_id ORDER BY id LIMIT 10",
        n: "LIMIT/OFFSET é simples: OFFSET = (página - 1) × tamanho. Mas para chegar à página 5000 o banco precisa LER e descartar as linhas anteriores, então fica cada vez mais lento. Também pode repetir ou pular itens se houver inserções entre uma página e outra.\nA paginação por keyset (ou 'cursor') guarda o último valor visto (ex.: id) e pede os próximos: WHERE id > último. Usa o índice e é rápida em qualquer profundidade, mas não permite 'pular para a página 50'.\nSEMPRE use ORDER BY junto: sem ele a ordem das páginas não é garantida. Dialetos: SQL Server usa OFFSET ... FETCH NEXT (ou TOP); Oracle 12c+ também aceita FETCH FIRST.",
        ex: `-- SQLite, MySQL, PostgreSQL\nSELECT * FROM produtos ORDER BY id LIMIT 10 OFFSET 20;\n\n-- SQL Server / Oracle 12c+ (padrão SQL)\nSELECT * FROM produtos ORDER BY id OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY;\n\n-- Keyset (rápido): "me dê os 10 seguintes ao id 120"\nSELECT * FROM produtos WHERE id > 120 ORDER BY id LIMIT 10;`,
        r: "sql/consultas/limit|sql/indices-performance/create-index", k: "paginar resultados|página 2|offset lento|limit offset|scroll infinito|cursor|próxima página" }),
  ]),

  cat("agregacao-avancada", "Agregação Avançada & Relatórios", "Concatenar valores, contar condicionalmente, pivotar, acumular e calcular percentuais.", [
    D("loja", `SELECT categoria,\n  COUNT(*) AS qtd,\n  GROUP_CONCAT(nome, ', ') AS produtos\nFROM produtos\nGROUP BY categoria;\n\n-- Cada banco tem seu nome: SQLite/MySQL = GROUP_CONCAT, PostgreSQL/SQL Server = STRING_AGG`,
      { s: "group-concat", t: "GROUP_CONCAT / STRING_AGG", d: "Junta os valores de um grupo em um único texto.", x: "GROUP_CONCAT(coluna, ', ')\nSTRING_AGG(coluna, ', ')",
        n: "Transforma várias linhas em uma só: lista de tags por artigo, produtos por pedido, e-mails por departamento. Costuma aceitar ORDER BY dentro da função para definir a ordem dos itens.\nNomes por banco: SQLite e MySQL usam GROUP_CONCAT; PostgreSQL e SQL Server (2017+) usam STRING_AGG; Oracle usa LISTAGG. Cuidado: o MySQL corta o resultado em 1024 caracteres por padrão.",
        ex: `-- SQLite / MySQL\nSELECT categoria, GROUP_CONCAT(nome, ', ') FROM produtos GROUP BY categoria;\n\n-- PostgreSQL / SQL Server 2017+\nSELECT categoria, STRING_AGG(nome, ', ' ORDER BY nome) FROM produtos GROUP BY categoria;`,
        r: "sql/avancado/group-by-having", k: "juntar valores em uma linha|lista separada por vírgula|concatenar grupo|string agg|listagg|group concat" }),
    D("loja", `SELECT\n  COUNT(*)                                   AS pedidos,\n  COUNT(*) FILTER (WHERE status = 'pago')    AS pagos,\n  COUNT(*) FILTER (WHERE status = 'cancelado') AS cancelados,\n  SUM(total) FILTER (WHERE status = 'pago')  AS receita_paga\nFROM pedidos;`,
      { s: "filter-agregacao", t: "Agregação condicional (FILTER)", d: "Conta ou soma só as linhas que atendem a uma condição, dentro do mesmo SELECT.", x: "COUNT(*) FILTER (WHERE status = 'pago')",
        n: "Permite calcular várias métricas com condições diferentes numa única passada pela tabela. FILTER é o padrão SQL (PostgreSQL, SQLite). Nos outros bancos o equivalente portável é SUM(CASE WHEN condição THEN 1 ELSE 0 END), que funciona em qualquer lugar.",
        ex: `-- Padrão SQL (PostgreSQL, SQLite)\nSELECT COUNT(*) FILTER (WHERE status = 'pago') AS pagos FROM pedidos;\n\n-- Funciona em TODOS os bancos (MySQL, SQL Server, Oracle...)\nSELECT SUM(CASE WHEN status = 'pago' THEN 1 ELSE 0 END) AS pagos FROM pedidos;`,
        r: "sql/agregacao-avancada/pivot-case|sql/funcoes/case-when", k: "contar com condição|sum com condição|várias métricas em uma consulta|count if|countif|agregação condicional" }),
    D("loja", `-- Uma linha por mês, uma coluna por status (tabela "pivotada")\nSELECT strftime('%m', data) AS mes,\n  SUM(CASE WHEN status = 'pago'      THEN total ELSE 0 END) AS pago,\n  SUM(CASE WHEN status = 'pendente'  THEN total ELSE 0 END) AS pendente,\n  SUM(CASE WHEN status = 'cancelado' THEN total ELSE 0 END) AS cancelado\nFROM pedidos\nGROUP BY mes\nORDER BY mes;`,
      { s: "pivot-case", t: "Pivot com CASE (linhas viram colunas)", d: "Transforma valores de uma coluna em colunas do resultado.", x: "SUM(CASE WHEN col = 'x' THEN valor ELSE 0 END) AS x",
        n: "Relatórios costumam pedir 'meses nas linhas e status nas colunas'. O SQL não tem um PIVOT universal (SQL Server e Oracle têm), mas o padrão SUM(CASE WHEN ...) funciona em todos os bancos.\nLimitação: as colunas precisam ser conhecidas de antemão. Para colunas dinâmicas é preciso montar o SQL por código (ou fazer o pivot na aplicação).",
        r: "sql/agregacao-avancada/filter-agregacao|sql/funcoes/case-when", k: "pivot|linhas viram colunas|tabela cruzada|crosstab|relatório por mês e status|transpor" }),
    D("loja", `-- Total acumulado dos pedidos pagos, em ordem de data\nSELECT id, data, total,\n  SUM(total) OVER (ORDER BY data, id) AS acumulado\nFROM pedidos\nWHERE status = 'pago'\nORDER BY data, id;`,
      { s: "running-total", t: "Total acumulado (running total)", d: "Soma progressiva: cada linha mostra o total até aqui.", x: "SUM(valor) OVER (ORDER BY data)",
        n: "Com uma função de janela, SUM(...) OVER (ORDER BY ...) soma da primeira linha até a linha atual. É a base de gráficos de evolução, saldo de conta e metas acumuladas.\nPara reiniciar a soma por grupo (ex.: por cliente ou por mês), acrescente PARTITION BY dentro do OVER. Sempre inclua um desempate no ORDER BY (como o id) para o resultado ser determinístico.",
        r: "sql/window-functions/over-partition|sql/window-functions/lag-lead", k: "soma acumulada|saldo progressivo|total até agora|running total|acumulado por data" }),
    D("loja", `-- Os 2 maiores pedidos de cada cliente\nSELECT *\nFROM (\n  SELECT cliente_id, id AS pedido, total,\n    ROW_NUMBER() OVER (PARTITION BY cliente_id ORDER BY total DESC) AS pos\n  FROM pedidos\n)\nWHERE pos <= 2\nORDER BY cliente_id, pos;`,
      { s: "top-n-por-grupo", t: "Top N por grupo", d: "Os N melhores de cada categoria, cliente ou departamento.", x: "ROW_NUMBER() OVER (PARTITION BY grupo ORDER BY valor DESC) ... WHERE pos <= N",
        n: "Pergunta clássica de entrevista e de relatório: 'os 3 produtos mais vendidos de cada categoria'. A solução moderna é numerar as linhas dentro de cada grupo com ROW_NUMBER e filtrar por posição na consulta de fora.\nUse ROW_NUMBER para exatamente N linhas por grupo, RANK para incluir empates (pode devolver mais que N) e DENSE_RANK para ranking sem 'buracos'.",
        r: "sql/window-functions/row-number-rank|sql/subqueries-conjuntos/subquery-correlacionada", k: "top 3 por categoria|melhores de cada grupo|ranking por grupo|maior de cada categoria|top n|mais vendidos por categoria" }),
    D("loja", `-- Quanto cada categoria representa do valor total em estoque\nSELECT categoria,\n  SUM(preco * estoque) AS valor_em_estoque,\n  ROUND(100.0 * SUM(preco * estoque) / SUM(SUM(preco * estoque)) OVER (), 1) AS percentual\nFROM produtos\nGROUP BY categoria\nORDER BY percentual DESC;`,
      { s: "percentual-do-total", t: "Percentual do total", d: "Quanto cada grupo representa do todo, em uma só consulta.", x: "100.0 * SUM(x) / SUM(SUM(x)) OVER ()",
        n: "Um OVER () vazio faz a função de janela olhar TODAS as linhas do resultado, dando o total geral ao lado de cada grupo. Assim você calcula participação (%) sem uma segunda consulta ou subconsulta.\nMultiplique por 100.0 (com decimal) para evitar a divisão inteira, que arredondaria tudo para 0.",
        r: "sql/window-functions/over-partition|sql/textos-numeros/funcoes-numericas", k: "porcentagem do total|participação|share|quanto representa|percentual por categoria" }),
    D("loja", `-- Subtotal por categoria + linha de TOTAL geral (o que o ROLLUP faz em PostgreSQL/MySQL/SQL Server)\nSELECT categoria, SUM(estoque) AS unidades FROM produtos GROUP BY categoria\nUNION ALL\nSELECT 'TOTAL', SUM(estoque) FROM produtos;`,
      { s: "totais-rollup", t: "Subtotais e total geral (ROLLUP)", d: "Linhas de subtotal e total no mesmo resultado, estilo relatório.", x: "GROUP BY ROLLUP (a, b)   -- ou UNION ALL no SQLite",
        n: "GROUP BY ROLLUP(a, b) gera os grupos normais, o subtotal por 'a' e o total geral. GROUP BY CUBE gera todas as combinações; GROUPING SETS permite escolher quais. Existem em PostgreSQL, MySQL (WITH ROLLUP), SQL Server e Oracle.\nO SQLite não tem ROLLUP: a alternativa portável, usada no exemplo, é juntar com UNION ALL uma consulta de total.",
        ex: `-- PostgreSQL / SQL Server / Oracle\nSELECT categoria, SUM(estoque) FROM produtos GROUP BY ROLLUP (categoria);\n\n-- MySQL\nSELECT categoria, SUM(estoque) FROM produtos GROUP BY categoria WITH ROLLUP;\n\n-- SQLite (e qualquer banco): UNION ALL\nSELECT categoria, SUM(estoque) FROM produtos GROUP BY categoria\nUNION ALL\nSELECT 'TOTAL', SUM(estoque) FROM produtos;`,
        r: "sql/joins-avancados/union|sql/agregacao-detalhada/sum-avg", k: "subtotal|total geral|rollup|cube|grouping sets|linha de total no relatório" }),
  ]),

  cat("modelagem", "Modelagem de Dados", "Como desenhar tabelas que não se contradizem: normalização, relacionamentos e escolhas de tipo.", [
    D("loja", `-- ❌ Tabela "tudo junto": o cliente é repetido em cada linha\nCREATE TABLE vendas_ruins (pedido INT, cliente TEXT, cidade TEXT, produto TEXT, preco REAL);\nINSERT INTO vendas_ruins VALUES\n  (1, 'Ana', 'Natal', 'Mouse', 80),\n  (1, 'Ana', 'Natal', 'Teclado', 150),\n  (2, 'Ana', 'Natal', 'Mouse', 80);\n\n-- A Ana mudou para Recife. Atualizamos... só o pedido 1:\nUPDATE vendas_ruins SET cidade = 'Recife' WHERE pedido = 1;\n\n-- Anomalia de atualização: agora a Ana mora em DUAS cidades\nSELECT DISTINCT cliente, cidade FROM vendas_ruins;`,
      { s: "normalizacao", t: "Normalização (1FN, 2FN, 3FN)", d: "Organizar as tabelas para não repetir informação e evitar dados contraditórios.", x: "1FN: valores atômicos · 2FN: sem dependência parcial da chave · 3FN: sem dependência de colunas não-chave",
        n: "Normalizar é guardar cada fato em UM só lugar. O exemplo mostra o problema: cliente e cidade repetidos em cada linha; se mudar em uma e esquecer outra, o banco passa a se contradizer (anomalia de atualização).\n1ª Forma Normal (1FN): cada célula tem um valor único (nada de 'Mouse, Teclado' numa coluna) e não há grupos repetidos. 2ª FN: toda coluna depende da chave INTEIRA, não só de parte dela (importa em chaves compostas). 3ª FN: colunas não-chave não dependem de outras colunas não-chave (a cidade depende do cliente, não do pedido).\nNa prática: separe em clientes, pedidos, produtos e itens_pedido, ligados por chaves estrangeiras (é exatamente o banco 'Loja' do SQL Lab). Desnormalizar de propósito (guardar um total calculado, por exemplo) é uma decisão válida por desempenho, desde que consciente.",
        u: "Sistemas transacionais (cadastros, pedidos, finanças)", a: "Relatórios analíticos pesados, onde dados repetidos de propósito (data warehouse) evitam JOINs caros", r: "sql/transacoes/primary-key|sql/transacoes/foreign-key|sql/modelagem/relacionamento-nn", k: "normalizar banco|primeira forma normal|terceira forma normal|dados repetidos|anomalia|modelagem|como organizar tabelas|1fn 2fn 3fn" }),
    D("loja", `CREATE TABLE artigos (id INTEGER PRIMARY KEY, titulo TEXT);\nCREATE TABLE tags (id INTEGER PRIMARY KEY, nome TEXT UNIQUE);\n\n-- Tabela ASSOCIATIVA: cada linha liga um artigo a uma tag\nCREATE TABLE artigos_tags (\n  artigo_id INTEGER REFERENCES artigos(id),\n  tag_id    INTEGER REFERENCES tags(id),\n  PRIMARY KEY (artigo_id, tag_id)   -- impede ligar o mesmo par duas vezes\n);\n\nINSERT INTO artigos (titulo) VALUES ('Guia de JOIN'), ('Flexbox do zero');\nINSERT INTO tags (nome) VALUES ('sql'), ('css'), ('iniciante');\nINSERT INTO artigos_tags VALUES (1, 1), (1, 3), (2, 2), (2, 3);\n\nSELECT a.titulo, GROUP_CONCAT(t.nome, ', ') AS tags\nFROM artigos a\nJOIN artigos_tags x ON x.artigo_id = a.id\nJOIN tags t ON t.id = x.tag_id\nGROUP BY a.id;`,
      { s: "relacionamento-nn", t: "Relacionamentos 1:N e N:N", d: "Como ligar tabelas: um-para-muitos com chave estrangeira, muitos-para-muitos com tabela associativa.", x: "N:N → tabela intermediária com duas chaves estrangeiras e chave primária composta",
        n: "1:N (um cliente tem muitos pedidos): coloque a chave estrangeira no lado 'muitos' (pedidos.cliente_id). 1:1 é raro; costuma ser uma tabela de extensão com a mesma chave.\nN:N (um artigo tem várias tags, uma tag está em vários artigos; aluno e curso): não cabe em duas tabelas. Crie uma terceira, associativa, com as duas chaves estrangeiras. A chave primária composta (artigo_id, tag_id) impede duplicatas.\nA tabela associativa também pode guardar dados do próprio relacionamento: na matrícula, a nota e as faltas do aluno naquele curso.",
        r: "sql/modelagem/normalizacao|sql/transacoes/foreign-key", k: "muitos para muitos|tabela associativa|tabela de ligação|relacionamento n:n|um para muitos|chave estrangeira|tags de artigos|aluno e curso" }),
    D("loja", `-- O erro clássico: dinheiro com ponto flutuante\nSELECT 0.1 + 0.2          AS soma,\n       0.1 + 0.2 = 0.3    AS igual_a_0_3,        -- 0 = falso!\n       ROUND(0.1 + 0.2, 2) = 0.3 AS arredondado_igual;\n\n-- Solução 1: guardar em CENTAVOS (inteiro)\nSELECT (1999 + 501) AS total_em_centavos, (1999 + 501) / 100.0 AS em_reais;\n\n-- Solução 2: tipo DECIMAL/NUMERIC (PostgreSQL, MySQL, SQL Server), que é exato`,
      { s: "tipos-de-dados", t: "Escolhendo tipos de dados (dinheiro, datas, texto)", d: "Qual tipo usar para cada informação, e por que dinheiro nunca é FLOAT.", x: "INTEGER · DECIMAL(12,2) · VARCHAR(n)/TEXT · DATE/TIMESTAMP · BOOLEAN",
        n: "Dinheiro: use DECIMAL(12,2) (exato) ou guarde em centavos como inteiro. FLOAT/REAL é aproximado e acumula erro (0.1 + 0.2 ≠ 0.3).\nDatas: use DATE, TIMESTAMP ou DATETIME, nunca texto solto como '10/03/24' (não ordena nem calcula). O SQLite não tem tipo de data próprio: guarde em texto ISO 'AAAA-MM-DD', que ordena corretamente.\nTexto: VARCHAR(n) limita o tamanho; TEXT não. CPF, CEP e telefone são TEXTO (têm zeros à esquerda e você não faz conta com eles). Identificadores: INTEGER auto-incremento é simples; UUID ajuda em sistemas distribuídos.\nBoolean: BOOLEAN no PostgreSQL; MySQL e SQLite usam 0/1.",
        r: "sql/funcoes/cast|sql/ddl/alter-add-column", k: "tipo para dinheiro|decimal ou float|guardar data|tipo de dado|varchar ou text|cpf como texto|float erro|centavos" }),
    D("loja", `ALTER TABLE clientes ADD COLUMN excluido_em TEXT;\n\n-- "Exclui" o cliente 2 sem apagar de verdade\nUPDATE clientes SET excluido_em = '2025-01-15' WHERE id = 2;\n\n-- Uma VIEW esconde os excluídos para o resto do sistema\nCREATE VIEW clientes_ativos AS SELECT * FROM clientes WHERE excluido_em IS NULL;\n\nSELECT (SELECT COUNT(*) FROM clientes) AS total_no_banco,\n       (SELECT COUNT(*) FROM clientes_ativos) AS ativos;`,
      { s: "soft-delete", t: "Exclusão lógica (soft delete)", d: "Marcar como excluído em vez de apagar, preservando histórico.", x: "ALTER TABLE t ADD COLUMN excluido_em TIMESTAMP;\nUPDATE t SET excluido_em = now() WHERE id = ...;",
        n: "Em vez de DELETE, você preenche uma coluna (excluido_em ou ativo = false). Os dados continuam para auditoria, relatórios e 'desfazer'. Combine com uma VIEW (ou um índice parcial) para o dia a dia só enxergar os ativos.\nRiscos: toda consulta precisa lembrar do filtro (por isso a view), restrições UNIQUE passam a colidir com registros 'excluídos' (resolva com índice único parcial) e dados pessoais podem precisar ser apagados de verdade por LGPD.",
        r: "sql/views-cte/create-view|sql/dml-detalhado/delete-vs-truncate", k: "exclusão lógica|não apagar de verdade|marcar como excluído|histórico de registros|lixeira|soft delete|lgpd" }),
  ]),

  cat("performance-sql", "Performance & Índices na Prática", "Como saber se uma consulta usa índice, e os erros que fazem tudo ficar lento.", [
    D("loja", `CREATE INDEX idx_status_data ON pedidos (status, data);\n\n-- ✅ Usa o índice: começa pela PRIMEIRA coluna (status)\nEXPLAIN QUERY PLAN SELECT * FROM pedidos WHERE status = 'pago' AND data >= '2024-06-01';\n\n-- ⚠️ Pula a primeira coluna: o índice não ajuda (varre a tabela)\nEXPLAIN QUERY PLAN SELECT * FROM pedidos WHERE data >= '2024-06-01';`,
      { s: "indice-composto", t: "Índice composto: a ordem das colunas importa", d: "Um índice em (a, b) serve para buscas por a, ou por a e b, mas não só por b.", x: "CREATE INDEX idx ON tabela (coluna_a, coluna_b);",
        n: "Pense numa lista telefônica ordenada por sobrenome e depois nome: ótima para achar 'Silva' ou 'Silva, Ana', inútil para achar todo mundo chamado 'Ana'. É a regra do 'prefixo mais à esquerda'.\nColoque primeiro as colunas comparadas com igualdade (status = 'pago') e depois a de faixa ou ordenação (data >= ...). Um índice a mais acelera leituras, mas deixa INSERT/UPDATE/DELETE mais lentos e ocupa espaço: crie os que suas consultas realmente usam.\nVerifique sempre com EXPLAIN: SEARCH ... USING INDEX é bom; SCAN é varredura completa.",
        r: "sql/indices-performance/create-index|sql/indices-performance/explain", k: "índice em duas colunas|índice composto|ordem das colunas no índice|query lenta|por que meu índice não é usado|multicoluna" }),
    D("loja", `CREATE INDEX idx_clientes_criado ON clientes (criado_em);\n\n-- ✅ Compara a COLUNA diretamente: usa o índice\nEXPLAIN QUERY PLAN\nSELECT * FROM clientes WHERE criado_em >= '2024-03-01' AND criado_em < '2024-04-01';\n\n-- ❌ Aplica uma FUNÇÃO na coluna: o índice é ignorado (SCAN)\nEXPLAIN QUERY PLAN\nSELECT * FROM clientes WHERE strftime('%Y-%m', criado_em) = '2024-03';`,
      { s: "funcao-na-coluna", t: "Função na coluna do WHERE mata o índice", d: "WHERE YEAR(data) = 2024 força o banco a calcular linha por linha, ignorando o índice.", x: "WHERE data >= '2024-01-01' AND data < '2025-01-01'   -- ✅\nWHERE YEAR(data) = 2024                              -- ❌",
        n: "Quando você envolve a coluna em uma função (YEAR(), LOWER(), SUBSTR(), coluna + 1), o banco não consegue usar o índice daquela coluna e precisa calcular a função para CADA linha.\nSolução: reescreva para comparar a coluna 'nua', mudando o outro lado (faixas de data com >= e <). Se for inevitável (ex.: busca sem diferenciar maiúsculas), crie um índice sobre a expressão (PostgreSQL, SQLite) ou coluna computada (MySQL, SQL Server).\nO mesmo vale para LIKE '%texto' (começa com curinga): LIKE 'texto%' usa índice, '%texto' não.",
        a: "Aplicar funções na coluna filtrada em tabelas grandes", r: "sql/subqueries-conjuntos/paginacao|sql/indices-performance/create-index|sql/consultas/like", k: "índice não é usado|consulta lenta com where|year no where|função na coluna|like com percentual no começo|sargable|where lento" }),
    D("loja", `CREATE INDEX idx_prod_cat_preco ON produtos (categoria, preco);\n\n-- Pede SÓ colunas que estão no índice: "COVERING INDEX" (nem toca na tabela)\nEXPLAIN QUERY PLAN SELECT categoria, preco FROM produtos WHERE categoria = 'Livros';\n\n-- SELECT * precisa voltar à tabela para buscar as outras colunas\nEXPLAIN QUERY PLAN SELECT * FROM produtos WHERE categoria = 'Livros';`,
      { s: "select-asterisco", t: "Evite SELECT * (índice de cobertura)", d: "Pedir só as colunas necessárias economiza rede, memória e pode dispensar a leitura da tabela.", x: "SELECT coluna1, coluna2 FROM ...   -- em vez de SELECT *",
        n: "SELECT * traz colunas que você não vai usar (às vezes textos longos), gasta rede e memória, e quebra o código se alguém adicionar ou renomear uma coluna.\nQuando todas as colunas pedidas estão dentro de um índice, o banco responde só com ele, sem consultar a tabela: é o 'índice de cobertura' (COVERING INDEX no plano). Com SELECT * isso nunca acontece.\nSELECT * é aceitável em exploração rápida e consultas pequenas; em código de aplicação, liste as colunas.",
        r: "sql/indices-performance/explain|sql/performance-sql/indice-composto", k: "select asterisco|trazer só as colunas necessárias|índice de cobertura|covering index|consulta mais rápida|select estrela" }),
  ]),

  cat("dialetos", "Diferenças entre Bancos (MySQL, PostgreSQL, SQLite, SQL Server)", "O SQL é um padrão, mas cada banco tem seu sotaque. Aqui estão as diferenças que mais atrapalham.", [
    D("loja", `-- SQLite aceita LIMIT. Veja nos outros bancos abaixo.\nSELECT nome, preco FROM produtos ORDER BY preco DESC LIMIT 3;`,
      { s: "limite-top", t: "LIMIT, TOP e FETCH (limitar linhas)", d: "Cada banco tem uma sintaxe para pegar só as primeiras linhas.", x: "LIMIT n  ·  TOP n  ·  FETCH FIRST n ROWS ONLY",
        n: "Pegar as primeiras N linhas é tão comum que cada banco inventou o seu jeito antes de o padrão existir. Sempre use ORDER BY junto, senão 'as primeiras' são arbitrárias.\nSQL Server coloca TOP logo depois do SELECT. Oracle 12c+, PostgreSQL e o padrão SQL aceitam FETCH FIRST ... ROWS ONLY.",
        ex: `-- MySQL, PostgreSQL, SQLite, MariaDB\nSELECT nome, preco FROM produtos ORDER BY preco DESC LIMIT 3;\n\n-- SQL Server (e Access)\nSELECT TOP 3 nome, preco FROM produtos ORDER BY preco DESC;\n\n-- Padrão SQL: Oracle 12c+, PostgreSQL, DB2, SQL Server (com OFFSET)\nSELECT nome, preco FROM produtos ORDER BY preco DESC FETCH FIRST 3 ROWS ONLY;`,
        r: "sql/consultas/limit|sql/subqueries-conjuntos/paginacao", k: "limit no sql server|top n|primeiras linhas|fetch first|limitar resultados|diferença entre bancos" }),
    D("loja", `CREATE TABLE exemplo_auto (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT);\nINSERT INTO exemplo_auto (nome) VALUES ('primeiro'), ('segundo');\n\n-- O id é gerado pelo banco. Para saber o último gerado:\nSELECT last_insert_rowid() AS ultimo_id;\nSELECT * FROM exemplo_auto;`,
      { s: "autoincrement", t: "Chave automática (AUTO_INCREMENT, SERIAL, IDENTITY)", d: "Cada banco gera ids sequenciais com uma sintaxe diferente.", x: "AUTO_INCREMENT · SERIAL / GENERATED ... AS IDENTITY · IDENTITY(1,1) · AUTOINCREMENT",
        n: "O mesmo CREATE TABLE não roda em todos os bancos justamente por causa da chave automática. Também muda a forma de descobrir o id recém-criado: LAST_INSERT_ID() (MySQL), RETURNING id (PostgreSQL/SQLite), SCOPE_IDENTITY() ou OUTPUT (SQL Server), last_insert_rowid() (SQLite).\nNo PostgreSQL moderno prefira GENERATED ... AS IDENTITY (padrão SQL) a SERIAL. UUIDs são uma alternativa quando o id precisa ser gerado fora do banco.",
        ex: `-- MySQL / MariaDB\nCREATE TABLE t (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(50));\n\n-- PostgreSQL (moderno)\nCREATE TABLE t (id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nome VARCHAR(50));\n\n-- SQL Server\nCREATE TABLE t (id INT IDENTITY(1,1) PRIMARY KEY, nome VARCHAR(50));\n\n-- SQLite\nCREATE TABLE t (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT);`,
        r: "sql/transacoes/primary-key|sql/dml-detalhado/returning", k: "id automático|auto increment|serial|identity|gerar id sequencial|chave primária automática|last insert id" }),
    D("loja", `-- Datas no SQLite: date(), strftime(), julianday()\n-- Atenção: 31/01 + 1 mês cai em 02/03 (fevereiro não tem dia 31); MySQL/PostgreSQL devolvem 29/02.\nSELECT date('2024-01-31', '+1 month')          AS mais_um_mes,\n       date('2024-03-15', '-7 days')           AS semana_passada,\n       strftime('%d/%m/%Y', '2024-03-15')      AS formatada,\n       CAST(julianday('2024-12-25') - julianday('2024-03-15') AS INTEGER) AS dias_entre;`,
      { s: "datas-por-banco", t: "Datas: somar dias, diferença e formatar (por banco)", d: "Aritmética de datas é onde os dialetos mais divergem.", x: "DATE_ADD · INTERVAL · DATEADD · date(x, '+1 day')",
        n: "Quase tudo relacionado a datas muda de banco para banco: data atual, somar/subtrair, diferença entre datas e formatação. Escreva isso isolado e comentado, porque é o primeiro ponto a quebrar numa migração.\nDica de modelagem: guarde datas em colunas do tipo certo (DATE/TIMESTAMP) e formate só na apresentação.",
        ex: `-- Data de hoje\n-- MySQL: CURDATE()  | PostgreSQL: CURRENT_DATE | SQL Server: CAST(GETDATE() AS DATE) | SQLite: date('now')\n\n-- Somar 7 dias\n-- MySQL:      DATE_ADD(data, INTERVAL 7 DAY)\n-- PostgreSQL: data + INTERVAL '7 days'\n-- SQL Server: DATEADD(day, 7, data)\n-- SQLite:     date(data, '+7 days')\n\n-- Diferença em dias\n-- MySQL: DATEDIFF(fim, inicio) | PostgreSQL: fim - inicio | SQL Server: DATEDIFF(day, inicio, fim)\n-- SQLite: julianday(fim) - julianday(inicio)\n\n-- Formatar como dd/mm/aaaa\n-- MySQL: DATE_FORMAT(d, '%d/%m/%Y') | PostgreSQL: TO_CHAR(d, 'DD/MM/YYYY')\n-- SQL Server: FORMAT(d, 'dd/MM/yyyy') | SQLite: strftime('%d/%m/%Y', d)`,
        r: "sql/funcoes/funcoes-data|sql/modelagem/tipos-de-dados", k: "somar dias a uma data|diferença entre datas|formatar data|data atual|date add|datediff|to char|mês anterior" }),
    Q({ s: "diferencas-dialetos", t: "Tabela de diferenças: MySQL × PostgreSQL × SQL Server × SQLite", d: "Resumo das diferenças de sintaxe que mais causam erro ao trocar de banco.", x: "Aspas · concatenação · LIMIT/TOP · auto-incremento · booleano · UPSERT",
      n: "Se um SQL que funcionava para de funcionar em outro banco, geralmente o motivo está nesta lista:\n• Aspas: texto SEMPRE entre aspas simples ('Ana'). Aspas duplas (\"nome\") são para NOMES de colunas/tabelas no PostgreSQL, SQLite e padrão SQL; o MySQL usa crases (`nome`) e o SQL Server usa colchetes ([nome]).\n• Maiúsculas/minúsculas: comparações de texto diferenciam caixa no PostgreSQL por padrão, mas não no MySQL e SQL Server (dependem da 'collation'). No PostgreSQL use ILIKE para busca sem caixa.\n• Concatenação: || (PostgreSQL, SQLite), CONCAT() (MySQL), + ou CONCAT() (SQL Server).\n• Limitar linhas: LIMIT, TOP ou FETCH FIRST.\n• Auto-incremento: AUTO_INCREMENT, SERIAL/IDENTITY, IDENTITY(1,1), AUTOINCREMENT.\n• Booleano: BOOLEAN (PostgreSQL), TINYINT(1) (MySQL), BIT (SQL Server), 0/1 (SQLite).\n• Upsert: ON CONFLICT, ON DUPLICATE KEY, MERGE.\n• Datas e strings: funções diferentes (veja 'Datas por banco').\n• JOIN FULL: não existe no MySQL; PostgreSQL, SQL Server e SQLite 3.39+ têm.\n• Transações: no MySQL, tabelas MyISAM não têm transação (use InnoDB, que é o padrão atual).",
      ex: `-- Mesmo objetivo, três dialetos: "nome completo em maiúsculas dos 5 primeiros clientes"\n\n-- PostgreSQL / SQLite\nSELECT UPPER(nome || ' ' || sobrenome) FROM clientes ORDER BY id LIMIT 5;\n\n-- MySQL\nSELECT UPPER(CONCAT(nome, ' ', sobrenome)) FROM clientes ORDER BY id LIMIT 5;\n\n-- SQL Server\nSELECT TOP 5 UPPER(nome + ' ' + sobrenome) FROM clientes ORDER BY id;`,
      r: "sql/dialetos/limite-top|sql/dialetos/autoincrement|sql/dialetos/datas-por-banco", k: "diferença entre mysql e postgres|sql server vs mysql|aspas duplas ou simples|migrar de banco|compatibilidade entre bancos|dialeto sql|sintaxe por banco" }),
  ]),

  cat("json-recursao", "JSON, CTE Recursiva e Sequências", "Consultar dados JSON dentro do banco, percorrer hierarquias e gerar séries sem tabela auxiliar.", [
    D("loja", `CREATE TABLE eventos (id INTEGER PRIMARY KEY, dados TEXT);\nINSERT INTO eventos (dados) VALUES\n  ('{"tipo":"clique","pagina":"/home","tags":["a","b","c"]}'),\n  ('{"tipo":"compra","valor":199.9,"itens":[{"sku":"X1","qtd":2}]}');\n\nSELECT id,\n  json_extract(dados, '$.tipo')         AS tipo,\n  json_extract(dados, '$.valor')        AS valor,\n  json_extract(dados, '$.itens[0].sku') AS primeiro_sku,\n  json_array_length(dados, '$.tags')    AS qtd_tags\nFROM eventos;`,
      { s: "json-no-sql", t: "Consultar JSON no banco", d: "Ler campos de documentos JSON guardados em uma coluna.", x: "json_extract(coluna, '$.campo')   -- SQLite\ncoluna ->> 'campo'               -- PostgreSQL / MySQL",
        n: "Bancos modernos guardam e consultam JSON diretamente, útil para dados semiestruturados (eventos, configurações, respostas de APIs). O caminho '$.campo.subcampo[0]' navega pelo documento.\nSintaxe: SQLite usa json_extract(); PostgreSQL usa os operadores -> (devolve JSON) e ->> (devolve texto) com o tipo JSONB, que também pode ser indexado; MySQL usa JSON_EXTRACT() ou ->>; SQL Server usa JSON_VALUE().\nQuando usar: dados com formato variável. Para dados que você filtra e junta o tempo todo, colunas normais continuam melhores e mais rápidas.",
        ex: `-- SQLite\nSELECT json_extract(dados, '$.tipo') FROM eventos;\n\n-- PostgreSQL (coluna do tipo JSONB)\nSELECT dados ->> 'tipo' FROM eventos WHERE dados @> '{"tipo":"compra"}';\n\n-- MySQL\nSELECT dados ->> '$.tipo' FROM eventos;\n\n-- SQL Server\nSELECT JSON_VALUE(dados, '$.tipo') FROM eventos;`,
        r: "sql/modelagem/normalizacao|sql/modelagem/tipos-de-dados", k: "json no banco|ler json em coluna|json extract|jsonb|dados semiestruturados|campo json" }),
    D("rh", `-- Organograma completo: começa na pessoa SEM gerente e desce nível a nível\nWITH RECURSIVE arvore (id, nome, nivel, caminho) AS (\n  SELECT id, nome, 0, nome\n  FROM funcionarios WHERE gerente_id IS NULL        -- ponto de partida\n  UNION ALL\n  SELECT f.id, f.nome, a.nivel + 1, a.caminho || ' > ' || f.nome\n  FROM funcionarios f\n  JOIN arvore a ON f.gerente_id = a.id              -- passo recursivo\n)\nSELECT substr('        ', 1, nivel * 2) || nome AS organograma, nivel, caminho\nFROM arvore\nORDER BY caminho;`,
      { s: "cte-recursiva", t: "CTE recursiva (hierarquias)", d: "Percorre estruturas em árvore: organogramas, categorias com subcategorias, comentários aninhados.", x: "WITH RECURSIVE nome AS (\n  SELECT ... -- parte inicial\n  UNION ALL\n  SELECT ... FROM tabela JOIN nome ON ... -- parte recursiva\n)",
        n: "Uma CTE recursiva tem duas partes ligadas por UNION ALL: a âncora (ponto de partida, aqui quem não tem gerente) e a parte recursiva, que se junta ao resultado anterior para achar o próximo nível. Repete até não encontrar mais linhas.\nÉ a forma padrão de percorrer uma árvore guardada com 'pai_id' (gerente_id, categoria_pai_id). Mantenha uma coluna de nível para limitar a profundidade e evitar laços infinitos se houver ciclos nos dados.\nSuporte: PostgreSQL, MySQL 8+, SQLite, Oracle e SQL Server (este sem a palavra RECURSIVE, só WITH).",
        r: "sql/views-cte/with-cte|sql/joins-avancados/self-join", k: "organograma|hierarquia|árvore|categorias e subcategorias|recursivo|percorrer níveis|with recursive|comentários aninhados" }),
    D("loja", `-- Gera os números de 1 a 10, sem precisar de nenhuma tabela\nWITH RECURSIVE n (x) AS (\n  SELECT 1\n  UNION ALL\n  SELECT x + 1 FROM n WHERE x < 10\n)\nSELECT x, x * x AS quadrado FROM n;\n\n-- Útil para gerar calendários: aqui, os 7 dias a partir de uma data\nWITH RECURSIVE dias (d) AS (\n  SELECT date('2024-03-01')\n  UNION ALL\n  SELECT date(d, '+1 day') FROM dias WHERE d < date('2024-03-07')\n)\nSELECT d, strftime('%w', d) AS dia_da_semana FROM dias;`,
      { s: "gerar-sequencia", t: "Gerar sequências de números e datas", d: "Cria uma série (1..N, calendário) direto na consulta, útil para preencher buracos de relatórios.", x: "WITH RECURSIVE n(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM n WHERE x < 10) SELECT x FROM n;",
        n: "Relatórios com 'dias sem vendas' falham porque não há linha para esses dias. A solução é gerar a série completa de datas e fazer LEFT JOIN com os dados reais, assim os dias vazios aparecem com zero.\nO PostgreSQL tem generate_series(1, 10) pronto, e o MySQL 8 e o SQL Server aceitam a mesma CTE recursiva (SQL Server sem a palavra RECURSIVE).",
        ex: `-- PostgreSQL: série pronta\nSELECT generate_series(1, 10) AS x;\nSELECT generate_series('2024-03-01'::date, '2024-03-07', '1 day');\n\n-- Qualquer banco com CTE recursiva (veja o exemplo executável ao lado)\nWITH RECURSIVE n (x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM n WHERE x < 10)\nSELECT x FROM n;`,
        r: "sql/json-recursao/cte-recursiva|sql/joins-avancados/left-right-join", k: "gerar números|gerar datas|calendário|série de datas|dias sem vendas|generate series|preencher buracos" }),
  ]),

  cat("seguranca-sql", "Segurança em SQL", "SQL injection, parâmetros e permissões: o mínimo para não expor seus dados.", [
    D("loja", `-- O que o seu código monta se o usuário digitar:   ' OR '1'='1\nSELECT 'SELECT * FROM clientes WHERE nome = ''' || '' || ''' OR ''1''=''1' || '''' AS consulta_montada;\n\n-- Executando essa consulta montada, a condição vira SEMPRE verdadeira:\nSELECT * FROM clientes WHERE nome = '' OR '1'='1';\n\n-- ✅ Com parâmetro (?), o que o usuário digita é só um DADO e nunca vira comando.`,
      { s: "sql-injection", t: "SQL Injection (e como evitar)", d: "Quando o texto do usuário vira parte do comando SQL e alguém assume o controle do banco.", x: "❌ \"SELECT * FROM t WHERE nome = '\" + entrada + \"'\"\n✅ SELECT * FROM t WHERE nome = ?   -- com parâmetro",
        n: "Se você monta o SQL concatenando texto digitado, o usuário pode inserir pedaços de SQL. O exemplo mostra o clássico ' OR '1'='1, que faz o WHERE devolver TODAS as linhas; versões mais graves leem outras tabelas ou apagam dados (como ';DROP TABLE...).\nA defesa é uma só: consultas parametrizadas (prepared statements). O banco recebe o comando e os valores separados, então o valor nunca é interpretado como SQL. Todo driver e ORM moderno oferece isso: use sempre.\nEscapar aspas manualmente não é suficiente. Complementos: dar ao usuário do banco da aplicação só as permissões necessárias, validar tipos de entrada e nunca expor mensagens de erro do banco ao visitante.",
        ex: `-- ❌ VULNERÁVEL (JavaScript)\ndb.query("SELECT * FROM clientes WHERE nome = '" + nomeDigitado + "'");\n\n-- ✅ SEGURO: parâmetro $1 / ?\ndb.query("SELECT * FROM clientes WHERE nome = $1", [nomeDigitado]);   // PostgreSQL (node-postgres)\ndb.query("SELECT * FROM clientes WHERE nome = ?", [nomeDigitado]);    // MySQL / SQLite\n\n-- Parâmetros valem para VALORES. Nomes de tabela/coluna dinâmicos exigem uma lista de permitidos (whitelist).`,
        u: "Toda consulta que envolva entrada do usuário (formulário, URL, API)", a: "Concatenar strings para montar SQL, mesmo 'só em um lugar'", r: "sql/seguranca-sql/grant-revoke|sql/consultas/select-where", k: "sql injection|injeção de sql|segurança no banco|prepared statement|consulta parametrizada|proteger formulário de login|hackear banco" }),
    Q({ s: "grant-revoke", t: "GRANT e REVOKE (permissões)", d: "Controla quem pode ler, alterar ou apagar o quê no banco.", x: "GRANT SELECT, INSERT ON tabela TO usuario;\nREVOKE INSERT ON tabela FROM usuario;",
      n: "A aplicação nunca deve conectar com o usuário administrador. Crie um usuário próprio com o mínimo de permissões necessárias (princípio do menor privilégio): se a conta vazar ou houver uma injeção, o estrago fica limitado.\nGRANT concede permissões (SELECT, INSERT, UPDATE, DELETE, e outras) em tabelas, colunas ou esquemas; REVOKE as retira. Papéis (ROLE) agrupam permissões para reaproveitar entre vários usuários.\nTípico: um usuário somente-leitura para relatórios, outro com leitura/escrita para a aplicação, e o administrador só para migrações. O SQLite não tem usuários (o acesso é pelo arquivo); este conceito vale para PostgreSQL, MySQL e SQL Server.",
      ex: `-- PostgreSQL\nCREATE ROLE app_leitura LOGIN PASSWORD 'troque-esta-senha';\nGRANT SELECT ON clientes, pedidos TO app_leitura;\n\nCREATE ROLE app_escrita LOGIN PASSWORD 'outra-senha-forte';\nGRANT SELECT, INSERT, UPDATE ON pedidos TO app_escrita;\n\nREVOKE UPDATE ON pedidos FROM app_escrita;\n\n-- MySQL\nCREATE USER 'relatorios'@'%' IDENTIFIED BY 'troque-esta-senha';\nGRANT SELECT ON loja.* TO 'relatorios'@'%';`,
      u: "Separar contas de aplicação, relatórios e administração", a: "Usar o usuário root/postgres/sa na aplicação", r: "sql/seguranca-sql/sql-injection", k: "permissões no banco|dar acesso ao usuário|usuário somente leitura|grant|revoke|criar usuário no banco|menor privilégio|role" }),
  ]),
];
